import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/cyclehire_w002.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# Load main dataset and compute Self-Containment Ratios
df = pd.read_csv(DATASET_PATH)
borough_departures = df.groupby('StartBorough')['Rental Id'].count()
borough_self_contained = df[df['StartBorough'] == df['EndBorough']].groupby('StartBorough')['Rental Id'].count()
ratios = (borough_self_contained / borough_departures).fillna(0)

# Load adjacency list and collect all boroughs
adj_df = pd.read_csv(ADJACENCY_PATH)
all_boroughs = set(adj_df['borough'].unique()) | set(adj_df['neighbor'].unique())
all_boroughs = list(all_boroughs)

# Create all_ratios with all boroughs, 0 for those not in StartBoroughs
all_ratios = pd.Series(index=all_boroughs, dtype=float)
all_ratios.update(ratios)
all_ratios = all_ratios.fillna(0)

# Build adjacency dictionary
adjacency = {}
for _, row in adj_df.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b not in adjacency:
        adjacency[b] = []
    adjacency[b].append(n)

# Compute neighbor averages
neighbor_averages = {}
for b in all_boroughs:
    neighbors = adjacency.get(b, [])
    neighbor_ratios = [all_ratios[neighbor] for neighbor in neighbors if neighbor in all_ratios]
    if len(neighbor_ratios) > 0:
        neighbor_averages[b] = np.mean(neighbor_ratios)
    else:
        neighbor_averages[b] = np.nan  # No neighbors

# Perform permutation test
num_permutations = 500
original_global_avg = all_ratios.mean()

observed = {b: (all_ratios[b], neighbor_averages[b]) for b in all_boroughs}
hot_spot_counts = {b: 0 for b in all_boroughs}
cold_spot_counts = {b: 0 for b in all_boroughs}

for perm in range(num_permutations):
    shuffled_ratios = np.random.permutation(all_ratios.values)
    shuffled_dict = {all_boroughs[i]: shuffled_ratios[i] for i in range(len(all_boroughs))}

    for b in all_boroughs:
        neighbors = adjacency.get(b, [])
        neighbor_ratios = [shuffled_dict[neighbor] for neighbor in neighbors if neighbor in shuffled_dict]
        if len(neighbor_ratios) > 0:
            neighbor_avg = np.mean(neighbor_ratios)
        else:
            neighbor_avg = np.nan

        if not np.isnan(neighbor_avg):
            if shuffled_dict[b] > original_global_avg and neighbor_avg > original_global_avg:
                hot_spot_counts[b] += 1
            elif shuffled_dict[b] < original_global_avg and neighbor_avg < original_global_avg:
                cold_spot_counts[b] += 1

# Identify significant hot/cold spots
hot_spots = []
cold_spots = []

for b in all_boroughs:
    original_ratio, original_neighbor_avg = observed[b]
    if np.isnan(original_neighbor_avg):
        continue

    is_hot_candidate = (original_ratio > original_global_avg) and (original_neighbor_avg > original_global_avg)
    is_cold_candidate = (original_ratio < original_global_avg) and (original_neighbor_avg < original_global_avg)

    if is_hot_candidate:
        p_hot = (hot_spot_counts[b] + 1) / (num_permutations + 1)
        if p_hot < 0.05:
            hot_spots.append((b, p_hot))
    elif is_cold_candidate:
        p_cold = (cold_spot_counts[b] + 1) / (num_permutations + 1)
        if p_cold < 0.05:
            cold_spots.append((b, p_cold))

# Format final answer
final_answer = []
for b, p in hot_spots:
    final_answer.append(f"{b} (HH, statistical method={p:.4f})")
for b, p in cold_spots:
    final_answer.append(f"{b} (LL, statistical method={p:.4f})")

if not final_answer:
    print("FINAL ANSWER: none")
else:
    print("FINAL ANSWER: " + ", ".join(final_answer))
